function negotiate(clientVersions, serverVersions) {
  const ok = clientVersions.filter((v) => serverVersions.includes(v));
  if (!ok.length) return { ok: false, error: 'UnsupportedProtocolVersion', serverSupports: serverVersions };
  return { ok: true, version: ok[0] };
}
console.log(JSON.stringify(negotiate(['2026-07-28'], ['2026-07-28'])));
